/* 퀘스트가 어느 거점 것인지: [거점 이름, 순번] (97 이상은 거점 밖) */
function qHub(zone,q){
  if(!q.xy)return ['필드·아이템에서 시작',99];
  if(q.gz&&q.gz!==zone)return ['다른 지역에서 받기 ('+q.gz+')',98];
  const [x,y]=q.xy.split(',').map(Number);const H=QHUB[zone];
  if(H){let best=null,bd=1e9;H.forEach((h,i)=>{const d=Math.hypot(h[1]-x,h[2]-y);if(d<bd){bd=d;best=[h[0],i]}});if(bd<14)return best}
  return [q.gv+' 근처 ('+Math.round(x)+', '+Math.round(y)+')',50+Math.round(x/10)];
}
